const test=require('node:test'),assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path');
test('Every domestic preset retains editable reviewed assets, purpose and unobstructed arrival aisle',async()=>{const {DOMESTIC_SCENES,domesticRecipe}=await import('../domestic-scenes.js');for(const [type,scene]of Object.entries(DOMESTIC_SCENES))for(const preset of Object.keys(scene.presets)){const r=domesticRecipe(type,preset,41);assert(r.requirements.length);for(const g of r.requirements)for(const item of g.items){assert(item.purpose);if(['roof','soil'].includes(item.asset))continue;const meta=JSON.parse(fs.readFileSync(path.join(__dirname,'../domestic-assets',item.asset+'.json'),'utf8'));assert(fs.existsSync(path.join(__dirname,'../domestic-assets',item.asset+'.glb')));assert.equal(meta.coordinates.units,'metres');const b=meta.geometry,angle=item.angle||0,c=Math.cos(angle),s=Math.sin(angle),points=[];for(const x of [b.bounds_min[0],b.bounds_max[0]])for(const z of [-b.bounds_max[1],-b.bounds_min[1]])points.push({x:item.x+x*c+z*s,z:item.z-x*s+z*c});const minX=Math.min(...points.map(p=>p.x)),maxX=Math.max(...points.map(p=>p.x)),minZ=Math.min(...points.map(p=>p.z)),maxZ=Math.max(...points.map(p=>p.z));assert(Math.max(...points.map(p=>Math.hypot(p.x,p.z)))<=g.radius,`${type}/${preset} ${item.asset} exceeds reserved footprint`);assert(!(minX<.7&&maxX>-.7&&minZ<7&&maxZ>1),`${type}/${preset} ${item.asset} blocks arrival aisle`);}}});
test('Preset grammar produces different deterministic layouts and connected entrances',async()=>{const {DOMESTIC_SCENES,domesticRecipe,completeDomesticPaths}=await import('../domestic-scenes.js'),{planAssembly}=await import('../tile-adapter.js');for(const [type,scene]of Object.entries(DOMESTIC_SCENES)){const variants=new Set();for(const preset of Object.keys(scene.presets)){const r=domesticRecipe(type,preset,41);variants.add(JSON.stringify(r.requirements));const resolve=()=>completeDomesticPaths(planAssembly(r,{requirementsByType:{[type]:r.requirements}}));const a=resolve();assert.deepEqual(a,resolve());assert.deepEqual(a.warnings,[],type+'/'+preset);for(const o of a.plans[0].placements){const external=a.plans[0].paths.find(p=>p.kind==='access'&&p.to===o.id),internal=a.plans[0].paths.find(p=>p.kind==='courtyard'&&p.to===o.id);assert(external&&internal);assert(Math.hypot(external.points.at(-1).x-internal.points[0].x,external.points.at(-1).z-internal.points[0].z)<1e-6);}}assert.equal(variants.size,Object.keys(scene.presets).length,type+' presets must materially differ');}});
